<style scoped>
.icon-shuttle-vehicle,
.icon-parking-barrier,
.icon-dining-cutlery,
.icon-pool-wave,
.icon-wellness-glyph,
.icon-room-service-bell,
.icon-iptv-screen,
.icon-iptv-chevron,
.icon-security-camera,
.icon-mini-bar-glass,
.icon-laundry-linens {
  transform-box: fill-box;
  transition:
    transform var(--duration-normal) var(--ease-premium),
    opacity var(--duration-normal) var(--ease-premium);
}

.icon-parking-barrier {
  transform-origin: 100% 100%;
}

.icon-wellness-glyph,
.icon-iptv-screen {
  transform-origin: 50% 50%;
}

.icon-room-service-bell,
.icon-mini-bar-glass {
  transform-origin: 50% 100%;
}

.icon-security-camera {
  transform-origin: 12% 90%;
}

.icon-laundry-linens {
  transform-origin: 50% 0%;
}

@keyframes facility-shuttle-drive {
  0%,
  100% {
    transform: translateX(0);
  }
  45%,
  62% {
    transform: translateX(7px);
  }
}

@keyframes facility-parking-barrier {
  0%,
  100% {
    transform: rotate(0deg);
  }
  45%,
  65% {
    transform: rotate(12deg);
  }
}

@keyframes facility-dining-lift {
  0%,
  100% {
    transform: translateY(0);
  }
  45%,
  70% {
    transform: translateY(-5px);
  }
}

@keyframes facility-pool-wave {
  0%,
  100% {
    transform: translateX(0);
  }
  50% {
    transform: translateX(4px);
  }
}

@keyframes facility-wellness-breathe {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.045);
  }
}

@keyframes facility-bell-ring {
  0%,
  100% {
    transform: rotate(0deg);
  }
  22% {
    transform: rotate(8deg);
  }
  48% {
    transform: rotate(-7deg);
  }
  72% {
    transform: rotate(4deg);
  }
}

@keyframes facility-iptv-screen {
  0%,
  100% {
    transform: scale(1);
  }
  45% {
    transform: scale(1.025);
  }
}

@keyframes facility-iptv-chevron {
  0%,
  100% {
    transform: translateY(0);
    opacity: 1;
  }
  50% {
    transform: translateY(-3px);
    opacity: 0.65;
  }
}

@keyframes facility-security-pan {
  0%,
  100% {
    transform: rotate(0deg);
  }
  35% {
    transform: rotate(-5deg);
  }
  70% {
    transform: rotate(4deg);
  }
}

@keyframes facility-glass-tilt {
  0%,
  100% {
    transform: rotate(0deg);
  }
  35% {
    transform: rotate(6deg);
  }
  68% {
    transform: rotate(-4deg);
  }
}

@keyframes facility-laundry-sway {
  0%,
  100% {
    transform: translateY(0) rotate(0deg);
  }
  40% {
    transform: translateY(-3px) rotate(2deg);
  }
  72% {
    transform: translateY(-1px) rotate(-1deg);
  }
}

@media (prefers-reduced-motion: no-preference) {
  .facility-tile:hover .icon-shuttle-vehicle,
  .facility-tile:focus-within .icon-shuttle-vehicle {
    animation: facility-shuttle-drive 1200ms var(--ease-premium);
  }

  .facility-tile:hover .icon-parking-barrier,
  .facility-tile:focus-within .icon-parking-barrier {
    animation: facility-parking-barrier 900ms var(--ease-premium);
  }

  .facility-tile:hover .icon-dining-cutlery,
  .facility-tile:focus-within .icon-dining-cutlery {
    animation: facility-dining-lift 1000ms var(--ease-premium);
  }

  .facility-tile:hover .icon-pool-wave-top,
  .facility-tile:focus-within .icon-pool-wave-top {
    animation: facility-pool-wave 1300ms var(--ease-premium);
  }

  .facility-tile:hover .icon-pool-wave-bottom,
  .facility-tile:focus-within .icon-pool-wave-bottom {
    animation: facility-pool-wave 1300ms var(--ease-premium) 140ms;
  }

  .facility-tile:hover .icon-wellness-glyph,
  .facility-tile:focus-within .icon-wellness-glyph {
    animation: facility-wellness-breathe 1200ms var(--ease-premium);
  }

  .facility-tile:hover .icon-room-service-bell,
  .facility-tile:focus-within .icon-room-service-bell {
    animation: facility-bell-ring 1100ms var(--ease-premium);
  }

  .facility-tile:hover .icon-iptv-screen,
  .facility-tile:focus-within .icon-iptv-screen {
    animation: facility-iptv-screen 900ms var(--ease-premium);
  }

  .facility-tile:hover .icon-iptv-chevron,
  .facility-tile:focus-within .icon-iptv-chevron {
    animation: facility-iptv-chevron 900ms var(--ease-premium) 60ms;
  }

  .facility-tile:hover .icon-security-camera,
  .facility-tile:focus-within .icon-security-camera {
    animation: facility-security-pan 1000ms var(--ease-premium);
  }

  .facility-tile:hover .icon-mini-bar-glass,
  .facility-tile:focus-within .icon-mini-bar-glass {
    animation: facility-glass-tilt 1100ms var(--ease-premium);
  }

  .facility-tile:hover .icon-laundry-linens,
